{
  "tools": [
    {
      "name": "add_envmap_probe",
      "title": "Add Envmap Probe",
      "toolset": "bridge_visuals",
      "description": "Add an environment reflection/ambient probe (EnvmapProbe) at a position with a cubic influence volume — captures local reflections and indirect light for nearby surfaces. IMPORTANT: a placed probe captures NOTHING until baked — follow with bake_reflections. Returns { created, gameObject } — gameObject.id is the probe object's GUID.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "GameObject name."
          },
          "position": {
            "type": "string",
            "description": "World position (centre of the probe). As \"x,y,z\" (or JSON {x,y,z})."
          },
          "size": {
            "type": "number",
            "description": "Cubic influence size in units (default 1024)."
          },
          "tint": {
            "type": "string",
            "description": "Tint applied to the captured environment. As \"r,g,b[,a]\" (0-1 floats)."
          },
          "feathering": {
            "type": "number",
            "description": "Edge feathering 0-1 for blending between overlapping probes."
          }
        },
        "required": []
      }
    },
    {
      "name": "create_npc_spawner",
      "title": "Create Npc Spawner",
      "toolset": "bridge_npc",
      "description": "Generate a spawner Component that instantiates an NPC prefab over time / in escalating waves at spawn points, capped by maxAlive. RUN's swarm backbone and Sasquatched's round-start spawn. After generating: set NpcPrefab via set_prefab_ref, set SpawnPoints (reuse place_patrol_route to make a set of empties, then assign_patrol_route with property='SpawnPoints'), trigger_hotload + get_compile_errors. Verify by watching the GameObject count over time in play mode. Networked spawns use NetworkSpawn() and are host-only.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Class/file name. Defaults to 'NpcSpawner'."
          },
          "directory": {
            "type": "string",
            "description": "Subdirectory under the project root. Defaults to 'Code'."
          },
          "mode": {
            "type": "string",
            "description": "'continuous' (one every interval), 'waves' (a batch every interval, waveCount times), 'burst' (one batch then stop). Default 'waves'. One of: continuous | waves | burst."
          },
          "count": {
            "type": "number",
            "description": "NPCs per wave (waves) or per batch (burst/continuous batch). Default 5."
          },
          "interval": {
            "type": "number",
            "description": "Seconds between spawns (continuous) or between waves (waves). Default 8."
          },
          "waveCount": {
            "type": "number",
            "description": "Number of waves (waves mode). Default 3."
          },
          "waveGrowth": {
            "type": "number",
            "description": "Multiply count each wave (&gt;1 = escalating). Default 1.0."
          },
          "radius": {
            "type": "number",
            "description": "Random scatter radius around a spawn point. Default 200."
          },
          "maxAlive": {
            "type": "number",
            "description": "Cap on concurrent live NPCs (important so swarms don't melt the frame rate). Default 12."
          },
          "networked": {
            "type": "boolean",
            "description": "When true (default), spawn via NetworkSpawn() (host-only, try/catch solo-safe) so clients see the NPCs; false = a plain local Clone for solo/edit testing."
          }
        },
        "required": []
      }
    },
    {
      "name": "run_csharp",
      "title": "Run",
      "toolset": "instance",
      "description": "Run a trusted C# method body on the engine main thread in game scope. Supply code OR an absolute path to a UTF-8 script file. Supports await and return (object); System, System.Linq, System.Threading, System.Threading.Tasks and Sandbox are imported. Parameters exchangeDirectory and cancellationToken are available. Example: return Game.ActiveScene?.Name; Engine/editor APIs are available, with editor types fully qualified. This has full local process privileges, may mutate live state, and does not create undo steps. Cancellation is cooperative: check cancellationToken in loops. Discover this tool through search_tools.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "code": {
            "type": "string",
            "description": "C# method body to execute. Mutually exclusive with path."
          },
          "path": {
            "type": "string",
            "description": "Absolute path to a UTF-8 C# method body, usually in the session exchange directory."
          }
        },
        "required": []
      }
    }
  ],
  "total": 402
}
